   256	public:
   257	  libraw_dng_stream(LibRaw_abstract_datastream *p)
   258	      : dng_stream((dng_abort_sniffer *)NULL, kBigBufferSize, 0),
   259	        parent_stream(p)
   260	  {
   261	    if (parent_stream)
   262	    {
   263	        parent_stream->buffering_off();
   264	      off = parent_stream->tell();
   265	      parent_stream->seek(0UL, SEEK_SET); /* seek to start */
   266	    }
   267	  }
   268	  ~libraw_dng_stream()
   269	  {
   270	    if (parent_stream)
   271	      parent_stream->seek(off, SEEK_SET);
   272	  }
   273	  virtual uint64 DoGetLength()
   274	  {
   275	    if (parent_stream)
   276	      return parent_stream->size();
   277	    return 0;
   278	  }
   279	  virtual void DoRead(void *data, uint32 count, uint64 offset)
   280	  {
   281	    if (parent_stream)
   282	    {
   283	      parent_stream->seek(offset, SEEK_SET);
   284	      parent_stream->read(data, 1, count);
   285	    }
   286	  }
